"use client";

import { useState } from "react";
import { Scissors, Calendar, Clock, BadgeCheck, MapPin, ChevronLeft, ChevronRight, User } from "lucide-react";
import { Button } from "@/components/ui/Button";
import { Card } from "@/components/ui/Card";

const SERVICES = [
    { id: 1, name: "Corte Tradicional", price: "R$ 45,00", time: "40 min" },
    { id: 2, name: "Barba Completa", price: "R$ 35,00", time: "30 min" },
    { id: 3, name: "Corte & Barba (Combo)", price: "R$ 70,00", time: "70 min" },
    { id: 4, name: "Sobrancelha", price: "R$ 15,00", time: "15 min" },
];

const BARBERS = [
    { id: 1, name: "Marciel", role: "Master", avatar: "https://api.dicebear.com/7.x/avataaars/svg?seed=Marciel" },
    { id: 2, name: "Junior", role: "Senior", avatar: "https://api.dicebear.com/7.x/avataaars/svg?seed=Junior" },
    { id: 3, name: "Thiago", role: "Specialist", avatar: "https://api.dicebear.com/7.x/avataaars/svg?seed=Thiago" },
];

const TIME_SLOTS = ["09:00", "10:00", "11:00", "13:00", "14:00", "15:00", "16:00", "17:00", "18:00"];

export default function ClientDashboard() {
    const [step, setStep] = useState(1);
    const [selectedService, setSelectedService] = useState<any>(null);
    const [selectedBarber, setSelectedBarber] = useState<any>(null);
    const [selectedDate, setSelectedDate] = useState("Hoje, 05 de Março");
    const [selectedTime, setSelectedTime] = useState("");
    const [isSuccess, setIsSuccess] = useState(false);

    const nextStep = () => setStep(step + 1);
    const prevStep = () => setStep(step - 1);

    const handleConfirm = () => {
        setIsSuccess(true);
    };

    if (isSuccess) {
        return (
            <div className="min-h-screen bg-[var(--color-dark-bg)] text-white flex items-center justify-center p-6 text-center">
                <div className="max-w-md w-full animate-fade-in-up">
                    <div className="w-20 h-20 bg-emerald-500/20 border border-emerald-500 rounded-full flex items-center justify-center mx-auto mb-6">
                        <BadgeCheck className="w-12 h-12 text-emerald-500" />
                    </div>
                    <h1 className="text-3xl font-bold mb-2">Agendamento Realizado!</h1>
                    <p className="text-gray-400 mb-8">Sua reserva foi confirmada com sucesso. Enviamos os detalhes para o seu email.</p>

                    <Card className="text-left mb-8 shadow-2xl">
                        <div className="space-y-4">
                            <div className="flex justify-between border-b border-[var(--color-dark-border)] pb-3">
                                <span className="text-gray-400">Serviço</span>
                                <span className="font-medium text-white">{selectedService?.name}</span>
                            </div>
                            <div className="flex justify-between border-b border-[var(--color-dark-border)] pb-3">
                                <span className="text-gray-400">Profissional</span>
                                <span className="font-medium text-white">{selectedBarber?.name}</span>
                            </div>
                            <div className="flex justify-between border-b border-[var(--color-dark-border)] pb-3">
                                <span className="text-gray-400">Data</span>
                                <span className="font-medium text-white">{selectedDate}</span>
                            </div>
                            <div className="flex justify-between">
                                <span className="text-gray-400">Horário</span>
                                <span className="font-medium text-[var(--color-primary-gold)]">{selectedTime}</span>
                            </div>
                        </div>
                    </Card>

                    <Button onClick={() => window.location.reload()} className="w-full">
                        VOLTAR AO INÍCIO
                    </Button>
                </div>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-[var(--color-dark-bg)] text-white pb-12 selection:bg-[var(--color-primary-gold)] selection:text-black">
            {/* Header */}
            <header className="bg-[var(--color-dark-card)] border-b border-[var(--color-dark-border)] p-4 sticky top-0 z-30">
                <div className="max-w-4xl mx-auto flex items-center justify-between">
                    <div className="flex items-center gap-3">
                        <div className="w-8 h-8 border border-[var(--color-primary-gold)] rounded-full flex items-center justify-center">
                            <Scissors className="w-4 h-4 text-[var(--color-primary-gold)]" />
                        </div>
                        <h2 className="font-bold tracking-widest text-sm uppercase">Marciel <span className="text-[var(--color-primary-gold)] font-light">Barber</span></h2>
                    </div>
                    <div className="w-8 h-8 rounded-full bg-[var(--color-dark-border)] overflow-hidden">
                        <img src="https://api.dicebear.com/7.x/avataaars/svg?seed=Client" alt="User" />
                    </div>
                </div>
            </header>

            <main className="max-w-4xl mx-auto px-4 mt-8">

                {/* Progress Tracker */}
                <div className="flex justify-between items-center mb-12 max-w-sm mx-auto">
                    {[1, 2, 3].map((i) => (
                        <div key={i} className="flex flex-col items-center gap-2">
                            <div className={`w-8 h-8 rounded-full flex items-center justify-center border transition-colors ${step >= i ? 'bg-[var(--color-primary-gold)] border-[var(--color-primary-gold)] text-black' : 'border-[var(--color-dark-border)] text-gray-500'}`}>
                                {step > i ? <BadgeCheck className="w-5 h-5" /> : i}
                            </div>
                            <span className={`text-[10px] uppercase tracking-widest ${step >= i ? 'text-white' : 'text-gray-500'}`}>
                                {i === 1 ? 'Serviço' : i === 2 ? 'Equipe' : 'Horário'}
                            </span>
                        </div>
                    ))}
                </div>

                {/* Step 1: Select Service */}
                {step === 1 && (
                    <div className="animate-fade-in-up">
                        <h1 className="text-2xl font-bold mb-2">Escolha o Serviço</h1>
                        <p className="text-gray-400 mb-8">Nossos profissionais estão prontos para te atender.</p>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            {SERVICES.map(s => (
                                <div
                                    key={s.id}
                                    onClick={() => setSelectedService(s)}
                                    className={`p-6 rounded-xl border transition-all cursor-pointer group ${selectedService?.id === s.id ? 'border-[var(--color-primary-gold)] bg-[var(--color-primary-gold)]/5' : 'border-[var(--color-dark-border)] bg-[var(--color-dark-card)] hover:border-gray-500'}`}
                                >
                                    <div className="flex justify-between items-start mb-4">
                                        <div>
                                            <h3 className="font-semibold text-lg">{s.name}</h3>
                                            <p className="text-gray-400 text-sm group-hover:text-gray-300 transition-colors uppercase tracking-tight flex items-center gap-1.5 mt-1">
                                                <Clock className="w-3 h-3" /> {s.time}
                                            </p>
                                        </div>
                                        <span className={`font-bold ${selectedService?.id === s.id ? 'text-[var(--color-primary-gold)]' : 'text-white'}`}>
                                            {s.price}
                                        </span>
                                    </div>
                                </div>
                            ))}
                        </div>
                        <div className="mt-8 flex justify-end">
                            <Button disabled={!selectedService} onClick={nextStep} className="w-full md:w-auto px-12">
                                PRÓXIMO PASSO
                            </Button>
                        </div>
                    </div>
                )}

                {/* Step 2: Select Barber */}
                {step === 2 && (
                    <div className="animate-fade-in-up">
                        <Button variant="ghost" onClick={prevStep} className="mb-6 -ml-4">
                            <ChevronLeft className="w-4 h-4 mr-1" /> Voltar
                        </Button>
                        <h1 className="text-2xl font-bold mb-2">Selecione o Profissional</h1>
                        <p className="text-gray-400 mb-8">Com quem você gostaria de agendar seu {selectedService?.name}?</p>
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                            {BARBERS.map(b => (
                                <div
                                    key={b.id}
                                    onClick={() => setSelectedBarber(b)}
                                    className={`p-6 rounded-xl border text-center transition-all cursor-pointer ${selectedBarber?.id === b.id ? 'border-[var(--color-primary-gold)] bg-[var(--color-primary-gold)]/5' : 'border-[var(--color-dark-border)] bg-[var(--color-dark-card)] hover:border-gray-500'}`}
                                >
                                    <div className="w-20 h-20 rounded-full bg-[var(--color-dark-bg)] mx-auto mb-4 border border-[var(--color-dark-border)] overflow-hidden">
                                        <img src={b.avatar} alt={b.name} className="w-full h-full object-cover" />
                                    </div>
                                    <h3 className="font-semibold">{b.name}</h3>
                                    <p className="text-[var(--color-primary-gold)] text-xs uppercase tracking-widest mt-1 font-light italic">{b.role}</p>
                                </div>
                            ))}
                        </div>
                        <div className="mt-12 flex justify-end">
                            <Button disabled={!selectedBarber} onClick={nextStep} className="w-full md:w-auto px-12">
                                CONFERIR HORÁRIOS
                            </Button>
                        </div>
                    </div>
                )}

                {/* Step 3: Select Time */}
                {step === 3 && (
                    <div className="animate-fade-in-up">
                        <Button variant="ghost" onClick={prevStep} className="mb-6 -ml-4">
                            <ChevronLeft className="w-4 h-4 mr-1" /> Voltar
                        </Button>
                        <h1 className="text-2xl font-bold mb-2">Escolha o Horário</h1>
                        <p className="text-gray-400 mb-8">Horários disponíveis para {selectedBarber?.name} no dia {selectedDate}.</p>

                        <div className="grid grid-cols-3 sm:grid-cols-4 md:grid-cols-5 gap-3">
                            {TIME_SLOTS.map(t => (
                                <button
                                    key={t}
                                    onClick={() => setSelectedTime(t)}
                                    className={`py-3 rounded-lg border text-sm font-medium transition-all ${selectedTime === t ? 'bg-[var(--color-primary-gold)] border-[var(--color-primary-gold)] text-black' : 'bg-transparent border-[var(--color-dark-border)] text-gray-400 hover:border-white hover:text-white'}`}
                                >
                                    {t}
                                </button>
                            ))}
                        </div>

                        <div className="mt-16 bg-[var(--color-dark-card)] border border-[var(--color-dark-border)] p-6 rounded-xl max-w-md mx-auto">
                            <h3 className="text-sm font-semibold tracking-widest uppercase text-gray-400 mb-6 text-center">Resumo Final</h3>
                            <div className="space-y-4 mb-8">
                                <div className="flex justify-between text-sm">
                                    <span className="text-gray-500 uppercase tracking-tighter">Serviço:</span>
                                    <span className="font-medium text-white">{selectedService?.name}</span>
                                </div>
                                <div className="flex justify-between text-sm">
                                    <span className="text-gray-500 uppercase tracking-tighter">Barbeiro:</span>
                                    <span className="font-medium text-white">{selectedBarber?.name}</span>
                                </div>
                                <div className="flex justify-between text-sm">
                                    <span className="text-gray-500 uppercase tracking-tighter">TOTAL:</span>
                                    <span className="font-bold text-[var(--color-primary-gold)]">{selectedService?.price}</span>
                                </div>
                            </div>
                            <Button disabled={!selectedTime} onClick={handleConfirm} className="w-full" size="lg">
                                CONFIRMAR AGENDAMENTO
                            </Button>
                        </div>
                    </div>
                )}

            </main>
        </div>
    );
}
